const { errorResponse } = require('../utils/response');

function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return errorResponse(res, 'Authentication token required', null, 401);
  }

  const token = authHeader.split(' ')[1];
  try {
    const decoded = verifyAccessToken(token);
    req.user = decoded;
    next();
  } catch (error) {
    if (error.name === 'TokenExpiredError') {
      return errorResponse(res, 'Session expired, please login again', null, 401);
    }
    return errorResponse(res, 'Invalid authentication token', null, 401);
  }
}

function authorizeRoles(...allowedRoles) {

return (req, res, next) => {
  if (!req.user) {
    return errorResponse(res, 'Unauthorized access', null, 401);
  }

const userRole = req.user.role ? req.user.role.toLowerCase() : '';
const formattedRoles = allowedRoles.map(r => r.toLowerCase());

if (userRole === 'super_admin' || formattedRoles.includes(userRole) || formattedRoles.includes('*')) {

      return next();
    }

    return errorResponse(res, 'Forbidden: You do not have permission to perform this action', null, 403);
  };
}

module.exports = {
  authenticate,
  authorizeRoles
};

const { errorResponse } = require('../utils/response');

function errorHandler(err, req, res, next) {
  console.error('[Error Middleware]', err);

  if (err.name === 'ValidationError') {
    return errorResponse(res, 'Validation Error', err.details || err.message, 422);
  }

  if (err.code === 'ER_DUP_ENTRY') {
    return errorResponse(res, 'A duplicate entry already exists with these details', err.sqlMessage, 409);
  }

  if (err.code === 'ER_NO_REFERENCED_ROW_2' || err.code === 'ER_ROW_IS_REFERENCED_2') {
    return errorResponse(res, 'Foreign key constraint violation', err.sqlMessage, 400);
  }

  const statusCode = err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  return errorResponse(res, message, process.env.NODE_ENV === 'development' ? err.stack : null, statusCode);
}

module.exports = errorHandler;

const multer = require('multer');
const path = require('path');
const fs = require('fs');

function createUploader(subfolder = 'documents', allowedTypes = /jpeg|jpg|png|gif|pdf|doc|docx|zip/) {
  const uploadDir = path.join(__dirname, '..', 'uploads', subfolder);
  if (!fs.existsSync(uploadDir)) {
    fs.mkdirSync(uploadDir, { recursive: true });
  }

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, uploadDir);
  },

  filename: (req, file, cb) => {
    const ext = path.extname(file.originalname).toLowerCase();
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1e9);
    cb(null, `${subfolder}-${uniqueSuffix}${ext}`);
  }
});

  const fileFilter = (req, file, cb) => {
    const extname = allowedTypes.test(path.extname(file.originalname).toLowerCase());
    const mimetype = allowedTypes.test(file.mimetype) || file.mimetype.includes('application/') || file.mimetype.includes('image/');

    if (extname || mimetype) {
      return cb(null, true);
    }
    cb(new Error('Invalid file type. Only standard documents and images are supported.'));
  };

  return multer({
    storage,
    limits: { fileSize: 10 * 1024 * 1024 }, // 10MB limit
    fileFilter
  });
}

// Special uploader for student imports: accepts CSV & Excel by extension only
// (xlsx MIME = application/vnd.openxmlformats-officedocument.spreadsheetml.sheet)
function createImportUploader() {
  const subfolder = 'imports';
  const uploadDir = path.join(__dirname, '..', 'uploads', subfolder);
  if (!fs.existsSync(uploadDir)) {
    fs.mkdirSync(uploadDir, { recursive: true });
  }

  filename: (req, file, cb) => {
    const ext = path.extname(file.originalname).toLowerCase();
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1e9);
    cb(null, `import-${uniqueSuffix}${ext}`);
  }
});

  const fileFilter = (req, file, cb) => {
    const ext = path.extname(file.originalname).toLowerCase();
    const allowedExts = ['.csv', '.xlsx', '.xls'];
    if (allowedExts.includes(ext)) {
      return cb(null, true);
    }
    cb(new Error('Only CSV (.csv) and Excel (.xlsx, .xls) files are allowed for import.'));
  };

  return multer({
    storage,
    limits: { fileSize: 10 * 1024 * 1024 }, // 10MB
    fileFilter
  });
}

