  const role = user?.role || 'guest';
  const userType = user?.userType || 'guest';

  const [existing] = await pool.query('SELECT * FROM chatbot_conversations WHERE id = ?', [conversationId]);
  if (existing.length > 0) {
    // Update title if needed
    return existing[0];
