  isSaving = signal<boolean>(false);

ngOnInit() {
  this.api.get<SchoolClass[]>('/academics/classes').subscribe(res => {
    this.classes.set(res.data || []);
    if (this.classes().length > 0) {
      this.selectedClass = String(this.classes()[0].class_id);
      this.onClassChange();
    }
  });
