  this.loadHostels();
  this.loadRooms();
}

canManage(): boolean {
  const role = this.auth.currentUser()?.role;
  return role === 'admin' || role === 'hostel_master';
}

loadHostels() {

this.loading.set(true);
this.api.get<HostelCategory[]>('/facilities/hostels').subscribe({
  next: (res) => {
    this.hostels.set(res.data || []);
    this.loading.set(false);
